# shellcheck shell=bash
# Generated By: Claude Code (claude-opus-5-5[1m])
#
# Sourced by every tests/test-*.sh right after it creates $TMP. Not a test
# itself: `make test-unit` runs only test-*.sh.
#
# What it guarantees: a test reaches no real sandbox, gateway, GitHub or Google
# account, and reads or writes nothing under the real home directory.
#   - Fail-closed fakes for every host tool sandbox.sh and scode can reach that
#     acts on something outside the test: each prints what was attempted and
#     exits 1. A test that models a tool puts its own fake earlier on PATH,
#     after sourcing this, and that one wins.
#   - HOME and XDG_CONFIG_HOME point into $TMP, so ~/sandboxes, ~/.claude,
#     ~/.codex and ~/.config/git/ignore are the test's own.
#
# A tool on this list being absent on one machine and installed on another is
# exactly what made tests behave differently on the host: openshell, podman, gh
# and code are missing in a sandbox, gws is installed in both.

[[ -n "${TMP:-}" && -d "$TMP" ]] || { echo "isolate.sh: source after TMP=\$(mktemp -d)" >&2; exit 1; }

ISOLATE_BIN="${TMP}/isolate-bin"
mkdir -p "$ISOLATE_BIN" "${TMP}/isolate-home/.config"
for isolate_tool in openshell podman gh code gws fzf; do
    printf '#!/bin/bash\necho "isolate.sh: real %s blocked: $*" >&2\nexit 1\n' "$isolate_tool" \
        > "${ISOLATE_BIN}/${isolate_tool}"
    chmod +x "${ISOLATE_BIN}/${isolate_tool}"
done
unset isolate_tool
export PATH="${ISOLATE_BIN}:${PATH}"
export HOME="${TMP}/isolate-home"
export XDG_CONFIG_HOME="${HOME}/.config"

# fake_openshell_list [NAME...]: model a gateway whose `sandbox list` holds
# exactly these containers (none by default). Creating a sandbox asks the
# gateway which openshell names are taken, so a test that mints one opts in;
# every other openshell call still fails closed.
fake_openshell_list() {
    local bin="${TMP}/fake-openshell-list" names=""
    mkdir -p "$bin"
    (( $# )) && names="$(printf '{"name":"%s","phase":"Ready"},' "$@")"
    cat > "${bin}/openshell" <<EOF
#!/bin/bash
if [[ "\$1 \$2" == "sandbox list" ]]; then
    printf '{"sandboxes":[%s],"next_page_token":""}\n' '${names%,}'
    exit 0
fi
echo "isolate.sh: real openshell blocked: \$*" >&2
exit 1
EOF
    chmod +x "${bin}/openshell"
    export PATH="${bin}:${PATH}"
}

# Existing-container fixtures represent an explicitly authorized empty set.
seed_provider_bindings() {
    local sandbox_dir="$1" profile="$2" stage
    stage="$(mktemp -d "${TMP}/bindings.XXXXXX")"
    python3 "${REPO_ROOT}/scripts/provider-profiles.py" "${HOME}/.codex" \
        "$stage" "$profile" '' >/dev/null
    cp "${stage}/bindings.json" "${sandbox_dir}/provider-profile-bindings.json"
}
